/**
 * Every waypoint task, command and option documented on the Hoggit DCS wiki
 * (data/hoggit.json, generated by scripts/gen-hoggit-data.py), validated against that
 * catalogue and appended to a waypoint's ComboTask.
 *
 * Shapes are the scripting-API tables the wiki documents: tasks as {id, params},
 * commands as WrappedAction{action={id, params}}, options as
 * WrappedAction{action={id='Option', params={name=<numeric id>, value}}} — the same
 * wrapping flight.ts already writes. The Mission Editor can add fields of its own; none of
 * these shapes has been opened in the ME or flown by this project.
 */
import { readFileSync } from 'node:fs';
import { packagePath } from '../paths.js';
import { asTable, luaArray, type LuaTable, type LuaValue } from './lua.js';
import { findGroup, findUnit, type FoundGroup } from './authoring.js';
import { resolveFamily } from './callsigns.js';

type Category = 'plane' | 'helicopter' | 'vehicle' | 'ship';
type Domain = 'Air' | 'Ground' | 'Naval';
interface ValueSpec { kind: string; values?: Record<string, unknown>; min?: number; max?: number }
interface ActionEntry {
  page: string; revid: number | null; kind: 'task' | 'command' | 'option'; taskType: string; categories: Category[]; since: string;
  id?: string; params?: Record<string, string>; required?: string[];
  optionIds?: Partial<Record<Domain, number>>; values?: ValueSpec; valuesByDomain?: Partial<Record<Domain, Record<string, number>>>;
}
export interface HoggitData {
  _source: string;
  enums: Record<string, Record<string, string | number>>;
  formations: Record<string, Record<string, number>>;
  actions: Record<string, ActionEntry>;
  callsigns: Record<string, { label: string; names: Record<string, string> }>;
}
interface ManualData { _source: string; _url: string; groups: Record<'aircraft' | 'ship' | 'vehicle', { label: string; menu: string; key: string | null }[]> }
let manualCache: ManualData | undefined;
/** ED's DCS User Manual (2022) Advanced Actions menus, linked to catalogue keys by literal name. */
export function manualData(): ManualData {
  return manualCache ??= JSON.parse(readFileSync(packagePath('data', 'me-manual-actions.json'), 'utf8')) as ManualData;
}
const manualGroup = (c: Category) => (c === 'plane' || c === 'helicopter' ? 'aircraft' : c) as 'aircraft' | 'ship' | 'vehicle';
function editorLabel(key: string, c: Category): string | undefined {
  return manualData().groups[manualGroup(c)]?.find(i => i.key === key)?.label;
}
/**
 * Categories an action applies to: the wiki's, plus a ship/vehicle category where ED's
 * manual lists it in that group's editor menu. The manual's aircraft chapter covers planes
 * and helicopters together, so it only adds aircraft where the wiki lists neither.
 */
function categoriesOf(key: string, a: ActionEntry): Category[] {
  const cats = new Set(a.categories);
  for (const c of ['ship', 'vehicle'] as const) if (editorLabel(key, c)) cats.add(c);
  if (!cats.has('plane') && !cats.has('helicopter') && editorLabel(key, 'plane')) { cats.add('plane'); cats.add('helicopter'); }
  return [...cats].sort() as Category[];
}
let cached: HoggitData | undefined;
export function hoggitData(): HoggitData {
  return cached ??= JSON.parse(readFileSync(packagePath('data', 'hoggit.json'), 'utf8')) as HoggitData;
}
const DOMAIN: Record<Category, Domain> = { plane: 'Air', helicopter: 'Air', vehicle: 'Ground', ship: 'Naval' };
const CATEGORIES = new Set(['plane', 'helicopter', 'vehicle', 'ship']);

export function listWaypointActions(category?: Category, kind?: 'task' | 'command' | 'option') {
  return Object.entries(hoggitData().actions)
    .filter(([key, a]) => (!category || categoriesOf(key, a).includes(category)) && (!kind || a.kind === kind))
    .map(([key, a]) => ({ key, kind: a.kind, taskType: a.taskType, categories: categoriesOf(key, a), page: a.page,
      editorLabel: category ? editorLabel(key, category) ?? null : undefined,
      ...(a.kind === 'option' ? { optionIds: a.optionIds, values: a.values?.kind,
        allowed: a.values?.kind === 'enum' ? a.values.values : a.values?.kind === 'range' ? { min: a.values.min, max: a.values.max } : undefined }
        : { params: a.params, required: a.required }) }));
}

/** Enum-typed parameters the wiki documents, checked when present. */
function enumFor(param: string): (string | number)[] | undefined {
  const e = hoggitData().enums;
  const values = (name: string) => Object.values(e[name] ?? {});
  switch (param) {
    case 'expend': return ['Auto', ...values('DCS_enum_AI_expend_list')];
    case 'pattern': return [...values('DCS_enum_AI_orbitPattern'), 'Anchored'];
    case 'designation': return values('DCS_enum_AI_designate_list');
    case 'modulation': return [0, 1];
    default: return undefined;
  }
}

function toLua(v: unknown, path: string): LuaValue {
  if (v === null || v === undefined) throw new Error(`${path}: null is not a DCS value`);
  if (Array.isArray(v)) return Object.fromEntries(v.map((x, i) => [i + 1, toLua(x, `${path}[${i + 1}]`)])) as LuaTable;
  if (typeof v === 'object') return Object.fromEntries(Object.entries(v as object).map(([k, x]) => [k, toLua(x, `${path}.${k}`)])) as LuaTable;
  if (typeof v === 'number' && !Number.isFinite(v)) throw new Error(`${path}: must be finite`);
  return v as LuaValue;
}

function checkType(name: string, declared: string, v: unknown): void {
  const t = declared.toLowerCase();
  const isVec2 = (x: unknown) => !!x && typeof x === 'object' && Number.isFinite((x as any).x) && Number.isFinite((x as any).y);
  if (t === 'boolean' && typeof v !== 'boolean') throw new Error(`${name} must be true or false`);
  if (t === 'string' && typeof v !== 'string') throw new Error(`${name} must be a string`);
  if (/^(number|distance|radians|azimuth|time)\b/.test(t) && !(typeof v === 'number' && Number.isFinite(v))) throw new Error(`${name} must be a number`);
  if (t === 'vec2' && !isVec2(v)) throw new Error(`${name} must be {x, y} in DCS metres`);
  const allowed = enumFor(name);
  if (allowed && !allowed.includes(v as string | number)) throw new Error(`${name} must be one of ${allowed.join(', ')}`);
}

/** groupId / unitId may be given as a group / unit NAME; resolved to the numeric id. */
function resolveIds(mission: LuaTable, params: Record<string, unknown>): Record<string, unknown> {
  const out = { ...params };
  if (typeof out.groupId === 'string') {
    const g = findGroup(mission, out.groupId);
    if (!g) throw new Error(`groupId: no group named '${out.groupId}'`);
    out.groupId = g.group.groupId;
  }
  if (typeof out.unitId === 'string') {
    const u = findUnit(mission, out.unitId);
    if (!u) throw new Error(`unitId: no unit named '${out.unitId}'`);
    out.unitId = u.unitId;
  }
  return out;
}

function optionValue(entry: ActionEntry, key: string, category: Category, value: unknown): LuaValue {
  const domain = DOMAIN[category];
  const spec = entry.values ?? { kind: 'unknown' };
  const enumValues = entry.valuesByDomain?.[domain] ?? (spec.kind === 'enum' ? spec.values as Record<string, number> : undefined);
  switch (spec.kind) {
    case 'enum': {
      const values = enumValues!;
      const v = typeof value === 'string' && value in values ? values[value] : value;
      if (!Object.values(values).includes(v as number)) throw new Error(`${key} (${domain}) takes ${Object.entries(values).map(([k, n]) => `${n}=${k}`).join(', ')}`);
      return v as number;
    }
    case 'boolean': if (typeof value !== 'boolean') throw new Error(`${key} takes true or false`); return value;
    case 'range': {
      if (typeof value !== 'number' || value < spec.min! || value > spec.max!) throw new Error(`${key} takes a number ${spec.min}..${spec.max}`);
      return value;
    }
    case 'number': case 'weapon_flag':
      if (typeof value !== 'number' || !Number.isFinite(value)) throw new Error(`${key} takes a number`); return value;
    case 'number_or_false':
      if (value !== false && !(typeof value === 'number' && value >= 0)) throw new Error(`${key} takes false or a non-negative number of seconds`); return value;
    case 'attributes':
      if (!Array.isArray(value) || !value.every(s => typeof s === 'string' && s.length)) throw new Error(`${key} takes a list of DCS attribute names`);
      return toLua(value, key);
    case 'formation': {
      const table = (spec.values as Record<string, Record<string, number>>)[category];
      if (!table) throw new Error(`${key} has no documented values for ${category} groups`);
      const v = typeof value === 'string' ? table[value] : value;
      if (!Object.values(table).includes(v as number)) throw new Error(`${key} for ${category} takes one of: ${Object.keys(table).join(', ')}`);
      return v as number;
    }
    default: throw new Error(`${key}: the wiki does not document its values; refusing to guess`);
  }
}

export interface ActionRequest { action: string; params?: Record<string, unknown>; value?: unknown }

/** Build the mission-file task table for one catalogue action, refusing anything undocumented. */
export function buildWaypointAction(mission: LuaTable, found: FoundGroup, req: ActionRequest) {
  const category = found.category as Category;
  if (!CATEGORIES.has(category)) throw new Error(`Group category '${found.category}' has no waypoint actions`);
  const entry = hoggitData().actions[req.action];
  if (!entry) throw new Error(`Unknown action '${req.action}'. Use dcs_list_waypoint_actions.`);
  const cats = categoriesOf(req.action, entry);
  if (!cats.includes(category)) throw new Error(`'${req.action}' is documented for ${cats.join(', ')}, not ${category} groups`);
  const warnings: string[] = [];
  const label = editorLabel(req.action, category);
  if (!label) warnings.push(`Not linked to an entry in the DCS User Manual (2022) editor menu for ${manualGroup(category)} groups; the manual may predate it, name it differently, or it may be scripting-only.`);
  else if (!entry.categories.includes(category)) warnings.push(`Offered for ${category} groups by the DCS User Manual editor menu ("${label}"); the Hoggit wiki does not list it for them.`);
  if (entry.kind === 'option') {
    if (req.params && Object.keys(req.params).length) throw new Error('Options take value, not params');
    const id = entry.optionIds?.[DOMAIN[category]];
    if (id === undefined) throw new Error(`'${req.action}' has no documented option id for ${DOMAIN[category]} groups`);
    const value = optionValue(entry, req.action, category, req.value);
    const params: LuaTable = { name: id, value };
    // Same extra fields flight.ts writes for the fixed-wing formation option.
    if (req.action === 'option:formation' && typeof value === 'number') Object.assign(params, { formationIndex: Math.floor(value / 65536), variantIndex: value % 65536 });
    return { task: { id: 'WrappedAction', params: { action: { id: 'Option', params } } } as LuaTable, warnings, page: entry.page };
  }
  if (req.value !== undefined) throw new Error(`'${req.action}' takes params, not value`);
  const declared = entry.params ?? {};
  const params = resolveIds(mission, req.params ?? {});
  if (entry.id === 'SetCallsign' && params.callname !== undefined && params.number !== undefined) {
    if (!Number.isInteger(params.number) || (params.number as number) < 1 || (params.number as number) > 9) throw new Error('SetCallsign number must be 1-9');
    if (category === 'plane' || category === 'helicopter') {
      const lead = luaArray(found.group.units)[0];
      params.callname = resolveFamily(String(lead?.type), String(found.group.task ?? ''), params.callname as number | string).family;
    } else if (!Number.isInteger(params.callname)) throw new Error('SetCallsign callname must be a number for ground groups');
  }
  for (const k of Object.keys(params)) if (!(k in declared)) throw new Error(`'${req.action}' has no documented parameter '${k}' (documented: ${Object.keys(declared).join(', ') || 'none'})`);
  for (const k of entry.required ?? []) if (params[k] === undefined) throw new Error(`'${req.action}' requires '${k}'`);
  for (const [k, v] of Object.entries(params)) checkType(k, declared[k], v);
  if (typeof params.groupId === 'number' && params.groupId === found.group.groupId && /Attack|Engage|Escort|Follow/.test(entry.id!))
    throw new Error(`'${req.action}' cannot target its own group`);
  if (entry.id === 'Script') warnings.push('Script is embedded mission Lua run by DCS; this server never executes it.');
  if (entry.id === 'TransmitMessage') warnings.push('TransmitMessage needs the audio file embedded in the mission (dcs_miz_embed_asset); its file reference format is not ME-verified.');
  const inner: LuaTable = { id: entry.id!, params: toLua(params, req.action) as LuaTable };
  const task = entry.kind === 'command' ? { id: 'WrappedAction', params: { action: inner } } as LuaTable : inner;
  return { task, warnings, page: entry.page };
}

/** Append to waypoint `index` (1-based) of a group's route as the next ComboTask entry. */
/**
 * Append one already-built task table to a waypoint's ComboTask, the way the editor
 * stores them (1-based `tasks`, each with enabled/auto/number). Exported so a composite
 * feature (troop transport, for one) can write a task the catalogue cannot express
 * without duplicating this bookkeeping.
 */
export function appendTaskTable(group: LuaTable, index: number, task: LuaTable): number {
  if (!Number.isInteger(index) || index < 1) throw new Error('waypointIndex is 1-based');
  const wp = asTable(asTable(asTable(group.route)?.points)?.[index]);
  if (!wp) throw new Error(`Waypoint ${index} does not exist (route has ${luaArray(asTable(group.route)?.points).length})`);
  const combo = asTable(wp.task);
  if (combo && combo.id !== 'ComboTask') throw new Error('Existing non-ComboTask waypoint task cannot be safely appended');
  const tasks = asTable(asTable(combo?.params)?.tasks) ?? {};
  const next = Math.max(0, ...Object.keys(tasks).map(Number).filter(Number.isFinite)) + 1;
  tasks[next] = { ...task, enabled: true, auto: false, number: next };
  if (!combo) wp.task = { id: 'ComboTask', params: { tasks } };
  else { const params = (combo.params ??= {}) as LuaTable; params.tasks = tasks; }
  return next;
}

export function addWaypointAction(mission: LuaTable, groupName: string, index: number, req: ActionRequest) {
  const found = findGroup(mission, groupName);
  if (!found) throw new Error(`No group named '${groupName}' in this mission`);
  const { task, warnings, page } = buildWaypointAction(mission, found, req);
  const next = appendTaskTable(found.group, index, task as LuaTable);
  return { group: groupName, waypointIndex: index, taskIndex: next, action: req.action, source: page, warnings };
}
